"""Freeze an explicitly assessed assignment week from persisted evidence; no question mutation."""
import json,pathlib,hashlib,datetime,sys,re,glob
R=pathlib.Path(__file__).resolve().parents[2];D=R/'audits/assignment-coverage';sys.path.insert(0,str(R/'scripts'));from validate import question_hash
load=lambda p:json.loads(p.read_text());sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def freeze(week,flags,extra_pages,coverage_note):
 seal=load(D/f'{week}-independent-prekey-seal.json');obs=[json.loads(l)for l in(D/f'{week}-independent-source-observations.jsonl').read_text().splitlines()];obsby={(o['sourceId'],o['physicalPage']):o for o in obs};ans={a['questionId']:a for a in seal['answers']};binding=load(D/'W01-W06-minimal-bindings.json');raw=load(R/f'data/question-batches/ASSIGN-{week}.json');qs=raw if isinstance(raw,list)else raw['questions'];reveal=load(D/f'{week}-independent-reveal.json');now=datetime.datetime.now(datetime.timezone.utc).isoformat();reviews=[];coverage=[]
 assert sha(R/seal['sourceObservationsPath'])==seal['sourceObservationsSha256'];assert sha(R/seal['initialResponsesPath'])==seal['initialResponsesSha256']
